#include <iostream>
#include <memory>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <signal.h>
#include <functional>
#include <queue>

class ConnectionPool;

struct Connection {
    int fd;
    std::string remote_addr;
    bool is_active;
    ConnectionPool* pool;

    Connection(int f, const std::string& addr, ConnectionPool* p)
        : fd(f), remote_addr(addr), is_active(true), pool(p) {}
    ~Connection() {
        if (fd >= 0) {
            std::cout << "Closing fd " << fd << std::endl;
            fd = -1;
        }
    }
};

class ConnectionPool {
private:
    std::vector<Connection*> active_connections_;
    std::vector<Connection*> idle_connections_;
    std::mutex mu_;

public:
    Connection* acquire(int fd, const std::string& addr) {
        std::lock_guard<std::mutex> lock(mu_);
        Connection* conn = new Connection(fd, addr, this);
        active_connections_.push_back(conn);
        return conn;
    }

    void release(Connection* conn) {
        std::lock_guard<std::mutex> lock(mu_);
        conn->is_active = false;
        auto it = std::find(active_connections_.begin(), active_connections_.end(), conn);
        if (it != active_connections_.end()) {
            active_connections_.erase(it);
            idle_connections_.push_back(conn);
        }
    }

    void drain_idle() {
        std::lock_guard<std::mutex> lock(mu_);
        for (auto* c : idle_connections_) {
            delete c;
        }
        idle_connections_.clear();
    }

    std::vector<Connection*> get_all_connections() {
        std::lock_guard<std::mutex> lock(mu_);
        std::vector<Connection*> all;
        all.insert(all.end(), active_connections_.begin(), active_connections_.end());
        all.insert(all.end(), idle_connections_.begin(), idle_connections_.end());
        return all;
    }

    size_t active_count() {
        std::lock_guard<std::mutex> lock(mu_);
        return active_connections_.size();
    }
};

class RequestHandler {
public:
    virtual void handle(Connection* conn) = 0;
    virtual ~RequestHandler() = default;
};

class EchoHandler : public RequestHandler {
public:
    void handle(Connection* conn) override {
        std::cout << "Handling request on fd " << conn->fd << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
};

class GracefulShutdownManager {
private:
    ConnectionPool& pool_;
    std::atomic<bool> shutting_down_{false};
    std::mutex shutdown_mu_;
    std::condition_variable shutdown_cv_;
    std::vector<Connection*> pending_cleanup_;

public:
    GracefulShutdownManager(ConnectionPool& pool) : pool_(pool) {}

    bool is_shutting_down() const { return shutting_down_.load(); }

    void initiate_shutdown() {
        shutting_down_.store(true);

        // Phase 1: Stop accepting new connections
        std::cout << "Phase 1: Stopping new connections" << std::endl;

        // Phase 2: Collect connections that need cleanup
        {
            std::lock_guard<std::mutex> lock(shutdown_mu_);
            pending_cleanup_ = pool_.get_all_connections();
        }

        // Phase 3: Wait for active requests to complete
        std::cout << "Phase 2: Waiting for active requests" << std::endl;
        int wait_cycles = 0;
        while (pool_.active_count() > 0 && wait_cycles < 10) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            wait_cycles++;
        }

        // Phase 4: Drain idle pool (frees idle connections)
        std::cout << "Phase 3: Draining idle pool" << std::endl;
        pool_.drain_idle();

        // Phase 5: Force-close remaining from our snapshot
        std::cout << "Phase 4: Force cleanup of remaining connections" << std::endl;
        finalize_cleanup();
    }

    void finalize_cleanup() {
        std::lock_guard<std::mutex> lock(shutdown_mu_);
        for (auto* conn : pending_cleanup_) {
            delete conn;
        }
        pending_cleanup_.clear();
    }
};

class Microservice {
private:
    ConnectionPool pool_;
    GracefulShutdownManager shutdown_mgr_;
    std::unique_ptr<RequestHandler> handler_;
    std::atomic<bool> running_{true};

public:
    Microservice() : shutdown_mgr_(pool_), handler_(std::make_unique<EchoHandler>()) {}

    void simulate_traffic() {
        for (int i = 0; i < 5 && running_; i++) {
            Connection* conn = pool_.acquire(100 + i, "127.0.0.1");
            handler_->handle(conn);
            pool_.release(conn);
        }
    }

    void shutdown() {
        running_ = false;
        shutdown_mgr_.initiate_shutdown();
    }

    void run() {
        std::thread traffic_thread([this]() { simulate_traffic(); });

        std::this_thread::sleep_for(std::chrono::milliseconds(200));
        shutdown();

        traffic_thread.join();
        std::cout << "Service stopped cleanly" << std::endl;
    }
};

int main() {
    Microservice svc;
    svc.run();
    return 0;
}
